-static struct lpc18xx_pin_caps *lpc18xx_get_pin_caps(unsigned pin)
-{
-	int i;
-
-	for (i = 0; i < ARRAY_SIZE(lpc18xx_pins); i++) {
-		if (lpc18xx_pins[i].number == pin)
-			return lpc18xx_pins[i].drv_data;
-	}
-
-	return NULL;
-}
