-static int lpc18xx_pconf_set_usb1(struct pinctrl_dev *pctldev,
-				  enum pin_config_param param,
-				  u32 param_val, u32 *reg)
-{
-	switch (param) {
-	case PIN_CONFIG_MODE_LOW_POWER:
-		if (param_val)
-			*reg &= ~LPC18XX_SCU_USB1_EPWR;
